INSERT INTO "producer" ("id", "user_id", "nip", "name", "country_code", "rating", "review_count", "technology", "verification_status", "created_at", "updated_at", "deleted_at", "production_scale", "inquiry_response_time_label", "showroom_visit_available", "showroom_visit_note", "description") VALUES ('e0030000-0000-4000-8000-0000000000ff', 'catalog-import:mkb', 'CATALOG-MKB', 'MKB Inwestycje', 'PL', NULL, 0, 'plyta-warstwowa-sip', 'not_submitted', '2026-10-09T10:39:16.076Z'::timestamptz, '2026-10-09T11:37:45.632Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Producent prefabrykowanych domów modułowych w technologii SIP: panele konstrukcyjne z rdzeniem izolacyjnym z pianki PIR, produkowane fabrycznie i montowane na działce. Oferta obejmuje siedem gotowych projektów od 52 do 175 m², od kompaktowych domów rekreacyjnych po duże domy rodzinne z garażem. Każdy projekt jest punktem wyjścia: elewację, okna, taras, układ i standard wykończenia można dopasować do inwestora.') ON CONFLICT DO NOTHING;
INSERT INTO "producer_delivery_country" ("producer_id", "country_code", "created_at") VALUES ('e0030000-0000-4000-8000-0000000000ff', 'PL', '2026-10-09T10:39:16.076Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_member" ("id", "producer_id", "user_id", "added_by", "created_at") VALUES ('1b0f6d41-2070-47f2-8774-2a7a071c43a6', 'e0030000-0000-4000-8000-0000000000ff', 'catalog-import:mkb', NULL, '2026-10-09T10:39:16.076Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('c2492b02-d3d8-4a9f-a95c-5b0ef8a2a325', 'e0030000-0000-4000-8000-0000000000ff', 'en', 'Producer of prefabricated modular houses in SIP technology: structural panels with a PIR foam insulating core, made in a factory and assembled on site. The range covers seven ready-made designs from 52 to 175 m², from compact leisure houses to large family homes with a garage. Each design is a starting point: the facade, windows, terrace, layout and finishing standard can be adapted to the investor.', NULL, NULL, '2026-10-09T10:39:16.076Z'::timestamptz, '2026-10-09T11:37:45.633Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('3ef427b9-d5aa-414a-9b90-9f0da0420be2', 'e0030000-0000-4000-8000-0000000000ff', 'de', 'Hersteller vorgefertigter Modulhäuser in SIP-Bauweise: tragende Paneele mit Dämmkern aus PIR-Schaum, im Werk gefertigt und auf dem Grundstück montiert. Das Angebot umfasst sieben fertige Entwürfe von 52 bis 175 m², von kompakten Freizeithäusern bis zu großen Familienhäusern mit Garage. Jeder Entwurf ist ein Ausgangspunkt: Fassade, Fenster, Terrasse, Grundriss und Ausbaustandard lassen sich an den Bauherrn anpassen.', NULL, NULL, '2026-10-09T10:39:16.076Z'::timestamptz, '2026-10-09T11:37:45.633Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('db09d428-059f-4233-afa6-0a5c1e18263e', 'e0030000-0000-4000-8000-0000000000ff', 'nl', 'Producent van geprefabriceerde modulaire huizen in SIP-technologie: constructiepanelen met een isolatiekern van PIR-schuim, in de fabriek gemaakt en op de bouwplaats gemonteerd. Het aanbod omvat zeven kant-en-klare ontwerpen van 52 tot 175 m², van compacte recreatiehuizen tot grote gezinswoningen met garage. Elk ontwerp is een uitgangspunt: gevel, ramen, terras, indeling en afwerkingsniveau kunnen op de bouwheer worden afgestemd.', NULL, NULL, '2026-10-09T10:39:16.076Z'::timestamptz, '2026-10-09T11:37:45.633Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('9c87e504-8de5-4a64-ae6b-80e53fd60f7c', 'Możliwość realizacji i wymagania formalne zależą od konkretnej działki oraz lokalnych ustaleń.', 'en', 'Feasibility and formal requirements depend on the specific plot and local regulations.', '2026-10-06T09:12:06.272Z'::timestamptz, '2026-10-06T09:12:06.272Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('770a3199-1d74-48f6-900a-257e3705d368', 'Możliwość realizacji i wymagania formalne zależą od konkretnej działki oraz lokalnych ustaleń.', 'de', 'Realisierbarkeit und formale Anforderungen hängen vom konkreten Grundstück und den örtlichen Vorgaben ab.', '2026-10-06T09:12:06.272Z'::timestamptz, '2026-10-06T09:12:06.272Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('eea7d9ec-ebb7-41fb-ae26-04cfba73092d', 'Możliwość realizacji i wymagania formalne zależą od konkretnej działki oraz lokalnych ustaleń.', 'nl', 'Haalbaarheid en formele vereisten zijn afhankelijk van het specifieke perceel en de lokale voorschriften.', '2026-10-06T09:12:06.272Z'::timestamptz, '2026-10-06T09:12:06.272Z'::timestamptz) ON CONFLICT DO NOTHING;
